PRAGMA foreign_keys=OFF;
CREATE TABLE IF NOT EXISTS "User" ("id" TEXT PRIMARY KEY,"email" TEXT NOT NULL UNIQUE,"name" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"role" TEXT NOT NULL DEFAULT 'USER',"active" INTEGER NOT NULL DEFAULT 1,"createdAt" TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS "Organization" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"createdAt" TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS "Membership" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"organizationId" TEXT NOT NULL,UNIQUE("userId","organizationId"));
CREATE TABLE IF NOT EXISTS "Session" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"expiresAt" TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS "Session_expiresAt_idx" ON "Session"("expiresAt");
CREATE TABLE IF NOT EXISTS "PasswordReset" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"expiresAt" TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS "RateLimit" ("id" TEXT PRIMARY KEY,"count" INTEGER NOT NULL DEFAULT 1,"expiresAt" TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS "Company" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"legalName" TEXT NOT NULL,"tradeName" TEXT NOT NULL DEFAULT '',"cnpj" TEXT NOT NULL,"city" TEXT NOT NULL DEFAULT '',"state" TEXT NOT NULL DEFAULT '',"activity" TEXT NOT NULL DEFAULT '',"products" TEXT NOT NULL DEFAULT '',"services" TEXT NOT NULL DEFAULT '',"keywords" TEXT NOT NULL DEFAULT '[]',"excludedTerms" TEXT NOT NULL DEFAULT '[]',"regions" TEXT NOT NULL DEFAULT '[]',"modalities" TEXT NOT NULL DEFAULT '[]',"minValue" NUMERIC,"maxValue" NUMERIC,"createdAt" TEXT NOT NULL,"updatedAt" TEXT NOT NULL,UNIQUE("organizationId","cnpj"));
CREATE TABLE IF NOT EXISTS "ContractingAgency" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"sphere" TEXT,"power" TEXT);
CREATE TABLE IF NOT EXISTS "Opportunity" ("detailImport" TEXT,"detailsHash" TEXT,"detailsSyncedAt" TEXT,"detailsRetryAt" TEXT,"detailsError" TEXT,"id" TEXT PRIMARY KEY,"agencyId" TEXT NOT NULL,"year" INTEGER NOT NULL,"sequence" INTEGER NOT NULL,"number" TEXT NOT NULL,"object" TEXT NOT NULL,"description" TEXT NOT NULL DEFAULT '',"city" TEXT NOT NULL,"state" TEXT NOT NULL,"modality" INTEGER NOT NULL,"modalityName" TEXT NOT NULL,"disputeMode" TEXT,"officialStatus" TEXT NOT NULL,"estimatedValue" NUMERIC,"publishedAt" TEXT NOT NULL,"opensAt" TEXT,"closesAt" TEXT,"officialUrl" TEXT NOT NULL,"contentHash" TEXT NOT NULL,"raw" TEXT NOT NULL,"discoveredAt" TEXT NOT NULL,"updatedAt" TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS "Opportunity_publishedAt_idx" ON "Opportunity"("publishedAt"); CREATE INDEX IF NOT EXISTS "Opportunity_closesAt_idx" ON "Opportunity"("closesAt"); CREATE INDEX IF NOT EXISTS "Opportunity_state_modality_idx" ON "Opportunity"("state","modality"); CREATE INDEX IF NOT EXISTS "Opportunity_estimatedValue_idx" ON "Opportunity"("estimatedValue"); CREATE INDEX IF NOT EXISTS "Opportunity_discoveredAt_idx" ON "Opportunity"("discoveredAt");
CREATE TABLE IF NOT EXISTS "OpportunityItem" ("id" TEXT PRIMARY KEY,"opportunityId" TEXT NOT NULL,"number" INTEGER NOT NULL,"description" TEXT NOT NULL,"quantity" NUMERIC,"unit" TEXT,"unitValue" NUMERIC,"raw" TEXT NOT NULL,UNIQUE("opportunityId","number"));
CREATE TABLE IF NOT EXISTS "OpportunityDocument" ("id" TEXT PRIMARY KEY,"opportunityId" TEXT NOT NULL,"officialId" TEXT NOT NULL,"title" TEXT NOT NULL,"url" TEXT NOT NULL,"type" TEXT,UNIQUE("opportunityId","officialId"));
CREATE TABLE IF NOT EXISTS "OpportunityMatch" ("id" TEXT PRIMARY KEY,"companyId" TEXT NOT NULL,"opportunityId" TEXT NOT NULL,"score" INTEGER NOT NULL,"reasons" TEXT NOT NULL,"version" INTEGER NOT NULL DEFAULT 1,"updatedAt" TEXT NOT NULL,UNIQUE("companyId","opportunityId")); CREATE INDEX IF NOT EXISTS "OpportunityMatch_companyId_score_idx" ON "OpportunityMatch"("companyId","score");
CREATE TABLE IF NOT EXISTS "Favorite" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"opportunityId" TEXT NOT NULL,"createdAt" TEXT NOT NULL,UNIQUE("userId","opportunityId"));
CREATE TABLE IF NOT EXISTS "OpportunityTracking" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"opportunityId" TEXT NOT NULL,"status" TEXT NOT NULL,"updatedAt" TEXT NOT NULL,UNIQUE("userId","opportunityId"));
CREATE TABLE IF NOT EXISTS "Alert" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"companyId" TEXT,"name" TEXT NOT NULL,"keywords" TEXT NOT NULL DEFAULT '[]',"state" TEXT,"city" TEXT,"agency" TEXT,"modality" INTEGER,"minValue" NUMERIC,"maxValue" NUMERIC,"minScore" INTEGER NOT NULL DEFAULT 0,"active" INTEGER NOT NULL DEFAULT 1,"email" INTEGER NOT NULL DEFAULT 0,"createdAt" TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS "Notification" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"alertId" TEXT NOT NULL,"opportunityId" TEXT NOT NULL,"title" TEXT NOT NULL,"readAt" TEXT,"emailedAt" TEXT,"createdAt" TEXT NOT NULL,UNIQUE("alertId","opportunityId")); CREATE INDEX IF NOT EXISTS "Notification_userId_readAt_idx" ON "Notification"("userId","readAt");
CREATE TABLE IF NOT EXISTS "AIAnalysis" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"opportunityId" TEXT NOT NULL,"contentHash" TEXT NOT NULL,"provider" TEXT NOT NULL,"model" TEXT NOT NULL,"version" INTEGER NOT NULL DEFAULT 1,"result" TEXT NOT NULL,"createdAt" TEXT NOT NULL,UNIQUE("userId","opportunityId","contentHash","provider","model","version"));
CREATE TABLE IF NOT EXISTS "SyncJob" ("id" TEXT PRIMARY KEY,"source" TEXT NOT NULL DEFAULT 'PNCP',"status" TEXT NOT NULL DEFAULT 'RUNNING',"startedAt" TEXT NOT NULL,"finishedAt" TEXT,"received" INTEGER NOT NULL DEFAULT 0,"created" INTEGER NOT NULL DEFAULT 0,"updated" INTEGER NOT NULL DEFAULT 0,"unchanged" INTEGER NOT NULL DEFAULT 0,"detailsDeferred" INTEGER,"detailPages" INTEGER,"detailsCompleted" INTEGER,"itemsImported" INTEGER,"documentsImported" INTEGER,"detailsFailed" INTEGER,"pendingDetails" INTEGER,"error" TEXT);
CREATE TABLE IF NOT EXISTS "SyncLog" ("id" TEXT PRIMARY KEY,"jobId" TEXT NOT NULL,"event" TEXT NOT NULL,"detail" TEXT NOT NULL,"createdAt" TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS "SyncCursor" ("id" TEXT PRIMARY KEY,"through" TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS "JobRequest" ("id" TEXT PRIMARY KEY,"type" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'PENDING',"createdAt" TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS "AuditLog" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"event" TEXT NOT NULL,"entityId" TEXT,"createdAt" TEXT NOT NULL); CREATE INDEX IF NOT EXISTS "AuditLog_userId_createdAt_idx" ON "AuditLog"("userId","createdAt");
CREATE TABLE IF NOT EXISTS "SyncPartition" ("modality" INTEGER PRIMARY KEY,"through" TEXT,"windowStart" TEXT,"windowEnd" TEXT,"nextPage" INTEGER NOT NULL DEFAULT 1,"retryAt" TEXT,"updatedAt" TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS "DetailImport" ("opportunityId" TEXT PRIMARY KEY,"contentHash" TEXT NOT NULL,"kind" TEXT NOT NULL DEFAULT 'itens',"nextPage" INTEGER NOT NULL DEFAULT 1,"createdAt" TEXT NOT NULL,"updatedAt" TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS "DetailPage" ("opportunityId" TEXT NOT NULL,"kind" TEXT NOT NULL,"page" INTEGER NOT NULL,"payload" TEXT NOT NULL,PRIMARY KEY("opportunityId","kind","page"));
